import Foundation

enum PhonePage {
    static let html = #"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Квиз Студия</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#101126;color:#f4f4ff}*{box-sizing:border-box}body{margin:0;padding:22px;max-width:650px;margin-inline:auto}header{color:#b7b5e7;margin:12px 0 28px}h1{font-size:28px;line-height:1.2}h2{font-size:22px;white-space:pre-wrap}p{line-height:1.5}input,textarea,select,button{font:inherit;font-size:17px;border-radius:12px;padding:15px;width:100%;margin:7px 0;border:1px solid #494574;background:#232242;color:inherit}button{background:#6657e8;border:0;font-weight:650;cursor:pointer;min-height:52px}button:disabled{opacity:.45;cursor:default}label.choice{display:flex;align-items:center;gap:14px;border:1px solid #494574;border-radius:12px;margin:10px 0;padding:12px}label.choice input{width:22px;height:22px;flex:none}label.choice:has(input:checked){border-color:#b7aaff;background:#35305b}.panel{background:#1a1935;border-radius:18px;padding:20px;margin:18px 0}.muted{color:#b9b5d1}.saved{color:#8ee0b1;white-space:pre-wrap}.answer{white-space:pre-wrap}#timer{float:right;font-size:22px;color:#ffcf7d}#notice{min-height:26px;color:#ffcf7d}small{line-height:1.5;display:block}li{margin:14px 0}a{color:#c5bfff}</style></head><body>
<header>КВИЗ СТУДИЯ <span id="timer"></span></header><h1 id="title">Подключение к квизу</h1><div id="join" class="panel"><p>Один телефон на команду</p><form id="joinForm"><label>Название команды — можно оставить пустым<input id="name" maxlength="60" autocomplete="organization" placeholder="Например, Знатоки"></label><button id="joinButton">Присоединиться</button></form><small class="muted">Оставайтесь в одной Wi-Fi-сети с Mac ведущего. Страницу можно открыть снова в этом же браузере: подключение и отправленные ответы сохранятся.</small></div>
<p id="team" class="muted"></p><p id="status" aria-live="polite"></p><div id="content" hidden><p id="round" class="muted"></p><h2 id="questionText"></h2><form id="answerForm"><div id="fields"></div><button id="send">Отправить ответ</button></form><p id="sent" class="saved"></p><div id="reveal" class="panel" hidden><strong>Правильный ответ</strong><p id="correct" class="answer"></p><p id="explanation" class="answer"></p></div></div><ol id="scores"></ol><p id="notice" role="status"></p>
<script>
const base=location.pathname.replace(/\/$/,''), key='quiz-studio:'+base;
const $=id=>document.getElementById(id);
function read(k){try{return localStorage.getItem(k)}catch{return null}}
function save(k,v){try{localStorage.setItem(k,v)}catch{}}
let token=read(key+':token')||'', active=null, rendered='', polling=false, networkLost=false;
let device=read(key+':device');if(!device){device=Array.from(crypto.getRandomValues(new Uint8Array(24))).map(x=>x.toString(16).padStart(2,'0')).join('');save(key+':device',device)}
async function api(path,body){const opts={cache:'no-store',headers:{Authorization:'Bearer '+token}};if(body!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const controller=new AbortController();opts.signal=controller.signal;const timeout=setTimeout(()=>controller.abort(),5000);try{const r=await fetch(base+path,opts);const data=await r.json();if(!r.ok){const error=new Error(data.error||'Ошибка подключения');error.status=r.status;throw error}return data}finally{clearTimeout(timeout)}}
function draft(){const a={};const choice=document.querySelector('input[name=choice]:checked');if(choice)a.choice=Number(choice.value);const text=$('textAnswer');if(text)a.text=text.value;const selects=[...$('fields').querySelectorAll('select')];if(selects.length)a.matches=Object.fromEntries(selects.map(s=>[s.name,s.value]));return a}
function rememberDraft(){if(!networkLost)$('notice').textContent='';if(active?.question)save(key+':draft:'+active.question,JSON.stringify(draft()))}
function fieldLabel(text){const p=document.createElement('p');p.textContent=text;return p}
function build(s){$('fields').replaceChildren();let old={};try{old=JSON.parse(read(key+':draft:'+s.question)||'{}')}catch{}
if(s.kind==='Один из четырёх'){(s.choices||[]).forEach((text,i)=>{const label=document.createElement('label');label.className='choice';const radio=document.createElement('input');radio.type='radio';radio.name='choice';radio.value=String(i);radio.checked=old.choice===i;label.append(radio,document.createTextNode(text));$('fields').append(label)})}
else if(s.kind==='Сопоставление'&&s.left){s.left.forEach(left=>{const label=document.createElement('label');label.append(fieldLabel(left.text));const select=document.createElement('select');select.name=left.key;const empty=document.createElement('option');empty.value='';empty.textContent='Выберите соответствие';select.append(empty);(s.right||[]).forEach((right,i)=>{const o=document.createElement('option');o.value=right.key;o.textContent=String.fromCharCode(1040+i)+'. '+right.text;select.append(o)});select.value=old.matches?.[left.key]||'';label.append(select);$('fields').append(label)})}
else {const text=document.createElement('textarea');text.id='textAnswer';text.rows=3;text.maxLength=1000;text.placeholder='Ответ команды';text.value=old.text||'';$('fields').append(text)}
$('fields').oninput=rememberDraft;$('fields').onchange=rememberDraft;rendered=s.question}
function render(s){active=s;$('join').hidden=true;$('title').textContent=s.title;$('team').textContent='Команда: '+s.team;$('status').textContent=s.message;$('timer').textContent=s.seconds!==undefined?'⏱ '+s.seconds+' с':'';$('content').hidden=!s.question;$('scores').replaceChildren();
if(s.question){if(rendered!==s.question)build(s);$('questionText').textContent=s.text;$('round').textContent=s.round||'';const sent=s.sent!==undefined;for(const control of $('answerForm').querySelectorAll('input,select,textarea,button'))control.disabled=!s.open||sent;$('answerForm').hidden=sent||s.phase==='answer'||s.phase==='answerPrompt';$('sent').textContent=sent?'✓ Ответ сохранён\n'+s.sent:'';$('reveal').hidden=s.correct===undefined;$('correct').textContent=s.correct||'';$('explanation').textContent=s.explanation||''}
for(const row of s.scores||[]){const li=document.createElement('li');li.textContent=row.place+'. '+row.name+' — '+row.points+' баллов';$('scores').append(li)}}
async function poll(){if(polling||!token)return;polling=true;try{const s=await api('/state');render(s);if(networkLost)$('notice').textContent='';networkLost=false}catch(e){networkLost=true;$('notice').textContent=e.status===401?'Подключение не найдено. Сканируйте актуальный QR-код ведущего.':'Связь потеряна. Переподключаемся автоматически…';for(const c of $('answerForm').querySelectorAll('input,select,textarea,button'))c.disabled=true;if(e.status===401){token='';save(key+':token','');$('join').hidden=false;$('content').hidden=true}}finally{polling=false;if(token)setTimeout(poll,1000)}}
$('joinForm').onsubmit=async e=>{e.preventDefault();$('joinButton').disabled=true;try{const result=await api('/join',{name:$('name').value,device});token=result.token;save(key+':token',token);save(key+':name',result.name);$('notice').textContent='';poll()}catch(error){$('notice').textContent=error.message}finally{$('joinButton').disabled=false}};
$('answerForm').onsubmit=async e=>{e.preventDefault();if(!active?.open)return;rememberDraft();$('send').disabled=true;try{await api('/answer',{question:active.question,answer:draft()});$('notice').textContent='Ответ сохранён на Mac ведущего';active.open=false;for(const c of $('answerForm').querySelectorAll('input,select,textarea,button'))c.disabled=true}catch(error){$('notice').textContent=error.message;$('send').disabled=false}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&token)poll()});
$('name').value=read(key+':name')||'';if(token){$('join').hidden=true;$('status').textContent='Восстанавливаем подключение…';poll()}
</script></body></html>
"""#
}
